import { readFile, writeFile, mkdir, unlink } from "node:fs/promises";
import { resolve, join } from "node:path";
import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import { chromium } from "@playwright/test";

// Deterministic asset import: creative pixels are generated by ImageGen.
// This importer slices, aligns, scales with nearest-neighbor, and packs them.
const root = resolve("assets/hedgehog/v1");
const spec = JSON.parse(await readFile(join(root, "generation.json"), "utf8"));
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
const manifest = {
  schemaVersion: 1,
  character: "煤球",
  version: "0.1.0",
  status: "animation-prototype",
  frameSize: { width: 128, height: 128 },
  anchor: { x: 64, y: 116 },
  defaultDisplaySize: 128,
  sampling: "nearest",
  animations: {},
};
const report = { generatedAt: new Date().toISOString(), clips: [] };
try {
  for (const clip of spec.clips) {
    const source = await readFile(join(root, "raw", `${clip.id}.png`));
    const processed = await page.evaluate(
      async ({ source, clip }) => {
        const image = new Image();
        image.src = source;
        await image.decode();
        const extracted = [];
        for (let i = 0; i < 8; i++) {
          // ImageGen may return a canvas such as 1774x887; partition every pixel
          // once using rounded boundaries, then export exact 128px cells.
          const sx = Math.round(((i % 4) * image.width) / 4);
          const sy = Math.round((Math.floor(i / 4) * image.height) / 2);
          const cw = Math.round((((i % 4) + 1) * image.width) / 4) - sx;
          const ch =
            Math.round(((Math.floor(i / 4) + 1) * image.height) / 2) - sy;
          const c = document.createElement("canvas");
          c.width = cw;
          c.height = ch;
          const ctx = c.getContext("2d", { willReadFrequently: true });
          ctx.drawImage(image, sx, sy, cw, ch, 0, 0, cw, ch);
          const pixels = ctx.getImageData(0, 0, cw, ch);
          let x0 = cw,
            y0 = ch,
            x1 = -1,
            y1 = -1,
            count = 0;
          for (let y = 0; y < ch; y++)
            for (let x = 0; x < cw; x++) {
              const offset = (y * cw + x) * 4;
              // A hard alpha edge avoids blurred fringes on the 128px game sprite.
              const visible = pixels.data[offset + 3] >= 96;
              pixels.data[offset + 3] = visible ? 255 : 0;
              if (visible) {
                x0 = Math.min(x0, x);
                x1 = Math.max(x1, x);
                y0 = Math.min(y0, y);
                y1 = Math.max(y1, y);
                count++;
              }
            }
          if (count < 100 || count / (cw * ch) > 0.78)
            throw new Error(
              `${clip.id}/${i}: empty sprite or non-transparent background`,
            );
          if (x0 < 2 || y0 < 2 || x1 >= cw - 2 || y1 >= ch - 2)
            throw new Error(
              `${clip.id}/${i}: sprite touches grid boundary; review source layout`,
            );
          ctx.putImageData(pixels, 0, 0);
          extracted.push({
            c,
            bounds: {
              x: x0,
              y: y0,
              w: x1 - x0 + 1,
              h: y1 - y0 + 1,
              bottom: y1 + 1,
            },
            alphaCoverage: count / (cw * ch),
          });
        }
        const maxW = Math.max(...extracted.map((f) => f.bounds.w));
        const maxH = Math.max(...extracted.map((f) => f.bounds.h));
        const maxFoot = Math.max(...extracted.map((f) => f.bounds.bottom));
        const height =
          clip.id === "sleep" ? 70 : clip.id === "happy" ? 94 : 100;
        // One scale per clip, never one scale per frame: preserve breathing and squash.
        const scale = Math.min(108 / maxW, height / maxH);
        const frames = extracted.map(({ c, bounds: b }, i) => {
          const out = document.createElement("canvas");
          out.width = out.height = 128;
          const ctx = out.getContext("2d", { willReadFrequently: true });
          ctx.imageSmoothingEnabled = false;
          const w = Math.round(b.w * scale),
            h = Math.round(b.h * scale);
          const lift =
            clip.id === "happy"
              ? Math.min(
                  18,
                  Math.max(0, Math.round((maxFoot - b.bottom) * scale)),
                )
              : 0;
          const x = Math.round(64 - w / 2),
            y = 116 - lift - h;
          ctx.drawImage(c, b.x, b.y, b.w, b.h, x, y, w, h);
          const outputPixels = ctx.getImageData(0, 0, 128, 128).data;
          let visible = 0,
            transparent = 0;
          for (let p = 3; p < outputPixels.length; p += 4) {
            if (outputPixels[p] === 0) transparent++;
            else if (outputPixels[p] === 255) visible++;
            else throw new Error("Unexpected fractional alpha");
          }
          return {
            png: out.toDataURL("image/png").split(",")[1],
            canvas: out,
            index: i,
            placement: { x, y, w, h, lift },
            visible,
            transparent,
          };
        });
        const sheet = document.createElement("canvas");
        sheet.width = 1024;
        sheet.height = 128;
        const sheetContext = sheet.getContext("2d");
        frames.forEach((f, i) => sheetContext.drawImage(f.canvas, i * 128, 0));
        return {
          sourceSize: { width: image.width, height: image.height },
          scale,
          sourceBounds: extracted.map((f) => f.bounds),
          frames: frames.map(({ canvas, ...f }) => f),
          sheet: sheet.toDataURL("image/png").split(",")[1],
        };
      },
      { source: `data:image/png;base64,${source.toString("base64")}`, clip },
    );
    await mkdir(join(root, "frames", clip.id), { recursive: true });
    const frameEntries = [];
    for (const f of processed.frames) {
      const file = `frames/${clip.id}/${String(f.index).padStart(2, "0")}.png`;
      const bytes = Buffer.from(f.png, "base64");
      await writeFile(join(root, file), bytes);
      frameEntries.push({
        file,
        durationMs: clip.duration[f.index],
        rect: { x: f.index * 128, y: 0, w: 128, h: 128 },
        sha256: createHash("sha256").update(bytes).digest("hex"),
      });
    }
    const uniqueFrames = new Set(frameEntries.map((f) => f.sha256)).size;
    if (uniqueFrames < 4)
      throw new Error(`${clip.id}: too few distinct frames (${uniqueFrames})`);
    await writeFile(
      join(root, "sheets", `${clip.id}.png`),
      Buffer.from(processed.sheet, "base64"),
    );
    manifest.animations[clip.id] = {
      label: clip.label,
      loop: clip.loop,
      returnTo: "idle",
      sheet: `sheets/${clip.id}.png`,
      frameCount: 8,
      durationMs: clip.duration.reduce((a, b) => a + b, 0),
      frames: frameEntries,
    };
    const timeline = frameEntries.flatMap((f) => [
      `file '${join(root, f.file).replaceAll("'", "'\\''")}'`,
      `duration ${f.durationMs / 1000}`,
    ]);
    timeline.push(
      `file '${join(root, frameEntries.at(-1).file).replaceAll("'", "'\\''")}'`,
    );
    const concat = join(root, "previews", `${clip.id}.ffconcat`);
    await writeFile(concat, `ffconcat version 1.0\n${timeline.join("\n")}\n`);
    const gif = spawnSync(
      "ffmpeg",
      [
        "-hide_banner",
        "-loglevel",
        "error",
        "-y",
        "-f",
        "concat",
        "-safe",
        "0",
        "-i",
        concat,
        "-filter_complex",
        "[0:v]split[a][b];[a]palettegen=reserve_transparent=1:stats_mode=full[p];[b][p]paletteuse=dither=none:alpha_threshold=128",
        "-fps_mode",
        "vfr",
        "-loop",
        clip.loop ? "0" : "-1",
        join(root, "previews", `${clip.id}.gif`),
      ],
      { encoding: "utf8" },
    );
    if (gif.status !== 0)
      throw new Error(`GIF export failed: ${gif.stderr || gif.error}`);
    await unlink(concat);
    report.clips.push({
      id: clip.id,
      uniqueFrames,
      sourceSize: processed.sourceSize,
      scale: processed.scale,
      sourceBounds: processed.sourceBounds,
      frames: processed.frames.map(({ png, ...f }) => f),
      gif: `previews/${clip.id}.gif`,
    });
    console.log(
      `${clip.id}: 8 frames, ${uniqueFrames} unique, transparent RGBA, GIF exported`,
    );
  }
  await writeFile(
    join(root, "manifest.json"),
    JSON.stringify(manifest, null, 2) + "\n",
  );
  await writeFile(
    join(root, "qa.json"),
    JSON.stringify(report, null, 2) + "\n",
  );
} finally {
  await browser.close();
}
